const atob = require('atob')
const btoa = require('btoa')
const crypto = require("crypto-js")

function base64ToByteArray(base64String) {
    const binaryString = atob(base64String)
    const byteArray = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
        byteArray[i] = binaryString.charCodeAt(i);
    }
    return byteArray;
}

function decryptStringAES(encryptedText, aesKey) {
    try {
        const keyBytes = base64ToByteArray(aesKey);
        const combinedBytes = base64ToByteArray(encryptedText);
        // Split into IV (first 16 bytes) and encrypted data
        const iv = combinedBytes.slice(0, 16);
        const encryptedBytes = combinedBytes.slice(16);

        // Convert Uint8Arrays to CryptoJS WordArrays
        const key = crypto.lib.WordArray.create(keyBytes);
        const ivWordArray = crypto.lib.WordArray.create(iv);
        const encryptedWordArray = crypto.lib.WordArray.create(encryptedBytes);
        // Decrypt using AES-CBC
        const decrypted = crypto.AES.decrypt(
            { ciphertext: encryptedWordArray },
            key,
            {
                iv: ivWordArray,
                mode: crypto.mode.CBC,
                padding: crypto.pad.Pkcs7
            }
        );

        // Convert to UTF-8 string
        const decryptedString = decrypted.toString(crypto.enc.Utf8);

        return decryptedString;
    } catch (error) {
        console.error('Decryption failed:', error);
        throw error;
    }
}


